# fullscreen.py: games get the whole screen (app bar hidden), big round buttons, Owl explains each game, gentle background music.
import base64, hashlib, os, sys
FULL = {'app/src/playzone/common.tsx': ('', '6c71462b3fafb72c0d5c1ebdae4e6509'), 'app/src/screens/PlayZoneScreen.tsx': ('', '4e6822bc1a10000320e858b7419f1056'), 'app/src/components/AppMenu.tsx': ('', '173c3d5c0b85a38859dff1a9d03ff260'), 'app/src/immersive.ts': ('', None), 'app/src/playzone/gameMusic.ts': ('', None), 'app/scripts/generate_game_music.py': ('', None), 'app/assets/music/loop-playful.mp3': ('', None), 'app/assets/music/loop-calm.mp3': ('', None)}
for p, (b, orig) in FULL.items():
    if orig is None:
        if os.path.exists(p): sys.exit(p + ' already exists; not applying')
    elif hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
